CREATE TYPE "SupplierStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "DocumentStatus" AS ENUM ('DRAFT','CONFIRMED','CANCELLED');
CREATE TYPE "ReservationStatus" AS ENUM ('RESERVED','COMMITTED','RELEASED');
CREATE TYPE "MovementType" AS ENUM ('PURCHASE','SALE','ADJUSTMENT_IN','ADJUSTMENT_OUT');
CREATE TABLE suppliers (id UUID PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE CHECK(btrim(code)<>''), name VARCHAR(200) NOT NULL CHECK(btrim(name)<>''), phone TEXT, address TEXT, status "SupplierStatus" NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE purchase_receipts (id UUID PRIMARY KEY, supplier_id UUID NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT ON UPDATE CASCADE, status "DocumentStatus" NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL, confirmed_by UUID, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TIMESTAMPTZ(3));
CREATE INDEX purchase_receipts_supplier_id_status_idx ON purchase_receipts(supplier_id,status);
CREATE TABLE purchase_receipt_items (id UUID PRIMARY KEY, receipt_id UUID NOT NULL REFERENCES purchase_receipts(id) ON DELETE RESTRICT ON UPDATE CASCADE, product_id UUID NOT NULL, product_code TEXT NOT NULL, product_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), unit_cost INTEGER NOT NULL CHECK(unit_cost>0), UNIQUE(receipt_id,product_id));
CREATE TABLE inventories (product_id UUID PRIMARY KEY, product_code TEXT NOT NULL, product_name TEXT NOT NULL, on_hand INTEGER NOT NULL DEFAULT 0, reserved INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, threshold INTEGER NOT NULL DEFAULT 5, updated_at TIMESTAMPTZ(3) NOT NULL, CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand AND version>=0 AND threshold>=0));
CREATE TABLE stock_movements (id UUID PRIMARY KEY, product_id UUID NOT NULL, reference_id UUID NOT NULL, type "MovementType" NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), actor_id UUID, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(reference_id,product_id,type));
CREATE INDEX stock_movements_product_id_created_at_idx ON stock_movements(product_id,created_at);
CREATE TABLE stock_adjustments (id UUID PRIMARY KEY, product_id UUID NOT NULL, expected_version INTEGER NOT NULL CHECK(expected_version>=0), counted INTEGER NOT NULL CHECK(counted>=0), reason TEXT NOT NULL CHECK(btrim(reason)<>''), status "DocumentStatus" NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL, confirmed_by UUID, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TIMESTAMPTZ(3));
CREATE TABLE stock_reservations (id UUID PRIMARY KEY, invoice_id UUID NOT NULL UNIQUE, status "ReservationStatus" NOT NULL DEFAULT 'RESERVED', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE stock_reservation_items (id UUID PRIMARY KEY, reservation_id UUID NOT NULL REFERENCES stock_reservations(id) ON DELETE RESTRICT ON UPDATE CASCADE, product_id UUID NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), UNIQUE(reservation_id,product_id));
